        elif op == "pop" and height > 0:
            height -= 1
    return height

def mean_list(lst):
    """Compute the result."""
    if not lst:
        return 0
    return sum(lst) / len(lst)

def count_evens(nums):
    """Compute the result."""
    c = 0
    for n in nums:
        if n % 2 == 0:
            c += 1
    return c

def clamp(x, lo, hi):
    """Compute the result."""
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

def binary_search(arr, target):
    """Compute the result."""
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        if arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def insertion_sort(a):
    """Compute the result."""
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

def count_char(s, ch):
    """Compute the result."""
    c = 0
    for x in s:
        if x == ch:
            c += 1
    return c

def strip_spaces(s):
    """Compute the result."""
    return "".join(ch for ch in s if ch != " ")

def last_index(lst, value):
    """Compute the result."""
    for i in range(len(lst) - 1, -1, -1):
        if lst[i] == value:
            return i
    return -1

def tuple_sum(t):
    """Compute the result."""
    s = 0
    for x in t:
        s += x
    return s

def is_even(n):
    """Compute the result."""
    return n % 2 == 0

def double_list(lst):
    """Compute the result."""
    return [x * 2 for x in lst]

def max_index(lst):
    """Compute the result."""
    if not lst:
        return -1
    best_i = 0
    for i in range(1, len(lst)):
        if lst[i] > lst[best_i]:
            best_i = i
    return best_i

def remove_negatives(lst):
    """Compute the result."""
    out = []
    for x in lst:
        if x >= 0:
            out.append(x)
    return out

def count_positive(lst):
    """Compute the result."""
    c = 0
    for x in lst:
        if x > 0:
            c += 1
    return c

def string_len(s):
    """Compute the result."""
    n = 0
    for _ in s:
        n += 1
    return n

def starts_with(s, prefix):
    """Compute the result."""
    if len(prefix) > len(s):
        return False
    for i in range(len(prefix)):
        if s[i] != prefix[i]:
            return False
    return True

def ends_with(s, suffix):
    """Compute the result."""
    if len(suffix) > len(s):
        return False
    start = len(s) - len(suffix)
    for i in range(len(suffix)):
        if s[start + i] != suffix[i]:
            return False
    return True

def rotate_left(lst, k):
    """Compute the result."""
    if not lst:
        return lst
    k = k % len(lst)
    return lst[k:] + lst[:k]

def unique_count(lst):
    """Compute the result."""
    seen = set()
    for x in lst:
        seen.add(x)
    return len(seen)

def second_largest(lst):
    """Compute the result."""
    if len(lst) < 2:
        return None
    a = max(lst)
    rest = [x for x in lst if x != a]
    if not rest:
        return None
    return max(rest)

def digit_count(n):
    """Compute the result."""
    n = abs(n)
    if n == 0:
        return 1
    c = 0
    while n:
        c += 1
        n //= 10
    return c

def is_ascending(lst):
    """Compute the result."""
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
    return True

def has_pair_sum(arr, target):
    """Compute the result."""
    seen = set()
    for x in arr:
        if target - x in seen:
            return True
        seen.add(x)
    return False

def matrix_trace(m):
    """Compute the result."""
    t = 0
    for i in range(len(m)):
        t += m[i][i]
    return t

def flatten_once(nested):
    """Compute the result."""
    out = []
    for sub in nested:
        for x in sub:
            out.append(x)
    return out

def running_max(lst):
    """Compute the result."""
    out = []
    cur = None
    for x in lst:
        if cur is None or x > cur:
            cur = x
        out.append(cur)
    return out

def count_words(s):
    """Compute the result."""
    parts = s.split()
    return len(parts)

def replace_char(s, old, new):
    """Compute the result."""
    out = []
    for ch in s:
        out.append(new if ch == old else ch)
    return "".join(out)

def zip_sum(a, b):
    """Compute the result."""
    n = min(len(a), len(b))
    return sum(a[i] + b[i] for i in range(n))

def mod_list(lst, m):
    """Compute the result."""
    return [x % m for x in lst]

def sign_list(lst):
    """Compute the result."""
    out = []
    for x in lst:
        if x > 0:
            out.append(1)
        elif x < 0:
            out.append(-1)
        else:
            out.append(0)
    return out

def copy_matrix(m):
    """Compute the result."""
    return [row[:] for row in m]

def col_sum(m, j):
    """Compute the result."""
    s = 0
    for row in m:
        s += row[j]
    return s
